def max_valid_window_sum(nums, k):
    max_sum = -1 * math.inf
    j = 0
    sum = 0
    num_negative = 0

    while j < len(nums):
        if nums[j] < 0:
            num_negative += 1

        sum += nums[j]

        if j >= k:
            sum -= nums[j - k]
            if nums[j - k] < 0:
                num_negative -= 1

            if num_negative == 1:
                max_sum = max(max_sum, sum)

        j += 1

    if max_sum == -1 * math.inf:
        max_sum = 0
    return max_sum

