class Solution {
public:
    int getMinDistance(vector<int>& nums, int target, int start) {

        int distance;
        int minDistance = -1;  

        for(int i = 0; i < nums.size(); i++){
            if(nums[i] == target){

                distance = i - start; 
                if(distance <= 0){
                    distance *= -1; 
                }

                if(minDistance == -1){
                    minDistance = distance; 
                }

                if (distance < minDistance) {
                    minDistance = distance;
                }

                if(distance == 0){ return 0;}
            }
        }

        if(minDistance == -1){
            return 0; 
        }

        return minDistance; 
    }
