    n = len(nums)
    if n < k:
        return 0

    current_sum = 0
    neg_count = 0
    max_sum = float('-inf')
    found_valid = False

    for i in range(k):
        current_sum += nums[i]
        if nums[i] < 0:
            neg_count += 1

    if neg_count <= 1:
